sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;
	$scope.updateUser=function(n){
		//alert("n.mobile:"+n.mobile);
		c.data.mobile =n.mobile;
		c.data.email =n.email;
		c.data.name =n.name;
		c.server.update().then(function(){
			c.data ={};
		});
	};
	//Test用
	$scope.confirmDelete =function(){
			//alert('How do you feel today?');
	};

};

sp_widget.script:
(function() {  /* populate the 'data' object */  /* e.g., data.table = $sp.getValue('table'); */
	data.userInfo=[];
	var gr = new GlideRecord("sys_user");
	gr.addQuery('sys_id',gs.getUserID());
	gr.query();
	while(gr.next()){
		data.userInfo.push({
			name:gr.name.toString(),
			mobile:gr.mobile_phone.toString(),
			email:gr.email.toString(),
		});
	}
})();
//gs.addInfoMessage("input--:"+input);
if(input){
	gs.addInfoMessage("---monile:"+input.mobile+"---email:"+input.email+"---name:"+input.name);

		var updataGr = new GlideRecord("sys_user");
		updataGr.addQuery('sys_id',gs.getUserID());
		updataGr.query();
		if(updataGr.next()){
		updataGr.mobile_phone = input.mobile;
		updataGr.email = input.email;
		updataGr.update();
	}
}
